//! Finds per-project build folders under a directory: node_modules, Python
//! virtual envs, Rust target folders and framework caches. Each is
//! regenerated by the project's install or build command.

use crate::util::{dir_size, remove_tree};
use rayon::prelude::*;
use serde::Serialize;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::time::UNIX_EPOCH;
use tauri::{AppHandle, Emitter};

pub static CANCEL: AtomicBool = AtomicBool::new(false);

#[derive(Serialize, Clone)]
#[serde(rename_all = "camelCase")]
pub struct Artifact {
    pub path: String,
    pub project: String,
    pub project_path: String,
    /// "node_modules", "venv", "target", "next", ...
    pub kind: String,
    pub label: String,
    pub restore: String,
    pub size: u64,
    pub files: u64,
    /// Seconds since epoch the folder last changed (roughly, the last install
    /// or build).
    pub modified: u64,
}

/// Folders never worth walking into.
const SKIP: &[&str] = &[
    ".git", ".hg", ".svn", "$recycle.bin", "system volume information", "windows", "program files",
    "program files (x86)", "appdata", "library", ".cache", ".cargo", ".rustup", ".npm", ".pnpm-store",
];

/// Decide whether `dir` (named `name`, inside `parent`) is a build artifact,
/// returning (kind, label, how to restore it).
fn classify(name: &str, dir: &Path, parent: &Path) -> Option<(&'static str, &'static str, &'static str)> {
    match name {
        "node_modules" if parent.join("package.json").is_file() => {
            Some(("node_modules", "node_modules", "npm / pnpm / yarn / bun install"))
        }
        ".venv" | "venv" | "env" | ".env" if dir.join("pyvenv.cfg").is_file() => {
            Some(("venv", "Python venv", "python -m venv, then reinstall requirements"))
        }
        "target" if parent.join("Cargo.toml").is_file() => Some(("target", "Rust target", "cargo build")),
        ".next" if parent.join("package.json").is_file() => Some(("next", "Next.js build", "next build / next dev")),
        ".nuxt" | ".output" if parent.join("nuxt.config.ts").is_file() || parent.join("nuxt.config.js").is_file() => {
            Some(("nuxt", "Nuxt build", "nuxt build / nuxt dev"))
        }
        ".svelte-kit" => Some(("svelte", "SvelteKit build", "vite dev / vite build")),
        ".turbo" => Some(("turbo", "Turborepo cache", "turbo run")),
        ".parcel-cache" => Some(("parcel", "Parcel cache", "parcel build")),
        ".angular" if parent.join("angular.json").is_file() => Some(("angular", "Angular cache", "ng build")),
        "unsloth_compiled_cache" => Some(("unsloth", "Unsloth compile cache", "re-created on the next training run")),
        ".mypy_cache" | ".ruff_cache" | ".pytest_cache" => Some(("pycache", "Python tool cache", "re-created on the next run")),
        "__pycache__" => None, // tiny and everywhere; not worth listing
        _ => None,
    }
}

struct Found {
    path: PathBuf,
    parent: PathBuf,
    kind: &'static str,
    label: &'static str,
    restore: &'static str,
}

fn walk(dir: &Path, depth: u32, max: u32, seen: &AtomicU64, app: &AppHandle) -> Vec<Found> {
    if CANCEL.load(Ordering::Relaxed) || depth > max {
        return vec![];
    }
    let n = seen.fetch_add(1, Ordering::Relaxed);
    if n % 200 == 0 {
        let _ = app.emit("project-walk", dir.to_string_lossy());
    }
    let Ok(rd) = std::fs::read_dir(dir) else { return vec![] };
    let subdirs: Vec<(String, PathBuf)> = rd
        .flatten()
        .filter(|e| e.file_type().is_ok_and(|t| t.is_dir() && !t.is_symlink()))
        .map(|e| (e.file_name().to_string_lossy().to_string(), e.path()))
        .collect();
    subdirs
        .par_iter()
        .flat_map(|(name, path)| {
            if let Some((kind, label, restore)) = classify(name, path, dir) {
                return vec![Found { path: path.clone(), parent: dir.to_path_buf(), kind, label, restore }];
            }
            let lower = name.to_ascii_lowercase();
            if SKIP.contains(&lower.as_str()) || name == "node_modules" {
                return vec![];
            }
            walk(path, depth + 1, max, seen, app)
        })
        .collect()
}

/// The project a build folder belongs to: the nearest folder up to `root`
/// that is a git repo, so `app/src-tauri/target` reads as "app", not
/// "src-tauri". Falls back to the folder that holds the artifact.
fn project_name(parent: &Path, root: &Path) -> String {
    let mut dir = Some(parent);
    while let Some(d) = dir {
        if d.join(".git").exists() {
            return d.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
        }
        if d == root {
            break;
        }
        dir = d.parent();
    }
    parent.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default()
}

/// Scan one or more folders (or whole drives). Overlapping roots are fine:
/// each build folder is listed once.
pub fn scan(app: &AppHandle, roots: &[String], max_depth: u32) -> Vec<Artifact> {
    CANCEL.store(false, Ordering::Relaxed);
    let seen = AtomicU64::new(0);
    let mut found: Vec<(PathBuf, Found)> = roots
        .par_iter()
        .map(PathBuf::from)
        .filter(|r| r.is_dir())
        .flat_map(|root| walk(&root, 0, max_depth, &seen, app).into_iter().map(move |f| (root.clone(), f)).collect::<Vec<_>>())
        .collect();
    let mut paths = std::collections::HashSet::new();
    found.retain(|(_, f)| paths.insert(f.path.to_string_lossy().to_ascii_lowercase()));
    let _ = app.emit("project-found-count", found.len());
    let mut out: Vec<Artifact> = found
        .par_iter()
        .filter_map(|(root, f)| {
            if CANCEL.load(Ordering::Relaxed) {
                return None;
            }
            let (size, files) = dir_size(&f.path);
            let modified = std::fs::metadata(&f.path)
                .and_then(|m| m.modified())
                .ok()
                .and_then(|t| t.duration_since(UNIX_EPOCH).ok())
                .map(|d| d.as_secs())
                .unwrap_or(0);
            let a = Artifact {
                path: f.path.to_string_lossy().to_string(),
                project: project_name(&f.parent, root),
                project_path: f.parent.to_string_lossy().to_string(),
                kind: f.kind.into(),
                label: f.label.into(),
                restore: f.restore.into(),
                size,
                files,
                modified,
            };
            let _ = app.emit("project-artifact", &a);
            Some(a)
        })
        .collect();
    out.sort_by_key(|i| std::cmp::Reverse(i.size));
    out
}

#[derive(Serialize, Clone)]
#[serde(rename_all = "camelCase")]
pub struct DeleteEvent {
    pub path: String,
    pub ok: bool,
    pub freed: u64,
    pub error: Option<String>,
}

/// Delete artifacts. Each path is checked again here, so nothing but a
/// recognised build folder can ever be removed through this command.
pub fn delete(app: &AppHandle, paths: &[String]) -> Vec<DeleteEvent> {
    paths
        .par_iter()
        .map(|p| {
            let path = PathBuf::from(p);
            let valid = path.file_name().and_then(|n| n.to_str()).zip(path.parent()).is_some_and(|(name, parent)| {
                classify(name, &path, parent).is_some()
            });
            let ev = if !valid {
                DeleteEvent { path: p.clone(), ok: false, freed: 0, error: Some("Not a recognised build folder".into()) }
            } else {
                let (size, _) = dir_size(&path);
                match remove_tree(&path) {
                    Ok(()) => DeleteEvent { path: p.clone(), ok: true, freed: size, error: None },
                    Err(e) => {
                        let left = dir_size(&path).0;
                        DeleteEvent { path: p.clone(), ok: false, freed: size.saturating_sub(left), error: Some(e.to_string()) }
                    }
                }
            };
            let _ = app.emit("project-deleted", &ev);
            ev
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn only_real_artifacts_are_recognised() {
        let root = std::env::temp_dir().join(format!("dc-proj-{}", std::process::id()));
        let web = root.join("web");
        std::fs::create_dir_all(web.join("node_modules")).unwrap();
        std::fs::create_dir_all(root.join("loose").join("node_modules")).unwrap();
        std::fs::write(web.join("package.json"), "{}").unwrap();
        assert!(classify("node_modules", &web.join("node_modules"), &web).is_some());
        // node_modules with no package.json beside it is left alone.
        let loose = root.join("loose");
        assert!(classify("node_modules", &loose.join("node_modules"), &loose).is_none());
        // A folder called target outside a Cargo project is not a Rust target.
        assert!(classify("target", &web.join("target"), &web).is_none());
        std::fs::remove_dir_all(&root).unwrap();
    }
}
